# Let me analyze the structure more carefully
# Maybe there's a pattern in how non-bg cells are grouped in each row

import numpy as np

input_grid = [
    [9, 2, 9, 8, 9, 1, 5, 5, 5, 7, 5, 5],
    [2, 5, 8, 5, 5, 5, 1, 5, 5, 9, 8, 5],
    [5, 9, 5, 5, 5, 2, 5, 5, 1, 5, 1, 5],
    [9, 5, 4, 5, 0, 5, 6, 5, 9, 1, 9, 5],
    [0, 5, 5, 7, 5, 0, 5, 5, 5, 5, 5, 5],
    [6, 5, 5, 5, 5, 5, 8, 8, 5, 5, 7, 5],
    [5, 5, 5, 5, 5, 5, 1, 5, 5, 4, 5, 9],
    [9, 5, 2, 5, 7, 5, 5, 0, 5, 1, 5, 7]
]

background = 5

# Analyze row by row structure
for r in range(8):
    row = input_grid[r]
    # Find runs of non-background
    non_bg_positions = [c for c in range(12) if row[c] != background]
    print(f"Row {r}: non-bg cols = {non_bg_positions}")

    # Check if there's a gap pattern
    if len(non_bg_positions) >= 2:
        gaps = [non_bg_positions[i+1] - non_bg_positions[i] - 1 for i in range(len(non_bg_positions)-1)]
        print(f"      Gaps between: {gaps}")

# Hypothesis: Maybe it's about mapping based on which "group" a cell belongs in
# e.g., left group vs right group

print("\n\nHypothesis: Left/Right split")
output_left_right = [[5 for _ in range(12)] for _ in range(8)]
for r in range(8):
    for c in range(12):
        if input_grid[r][c] != background:
            if c < 6:
                output_left_right[r][c] = input_grid[r][c] + 1
            else:
                output_left_right[r][c] = input_grid[r][c] - 1
for row in output_left_right:
    print(row)

# Hypothesis: Each unique color gets mapped based on its first column position
print("\n\nHypothesis: First-column rank mapping")
color_first_col = {}
for r in range(8):
    for c in range(12):
        if input_grid[r][c] not in color_first_col:
            color_first_col[input_grid[r][c]] = c

first_col_rank = {c: r for r, c in sorted(color_first_col.items())}
print(f"Color -> first col: {color_first_col}")
print(f"First-col ranks (sorted by first col): {first_col_rank}")

output_first_col = [[first_col_rank.get(input_grid[r][c], background) for c in range(12)] for r in range(8)]
for row in output_first_col:
    print(row)

